WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?zone_name .
  ?temp brick:isPointOf|brick:hasSuperclass ?zone .
}

SELECT DISTINCT ?zoneName ?temp ?temp_ts WHERE {
  ?zone brick:isPartOf* ?any .
  ?zone a brick:Zone .
  ?zone rdfs:label ?zoneName .
  ?temp a brick:Air_Temperature .
  ?temp brick:isPointOf ?zone .
  OPTIONAL { ?temp ref:hasTimeseriesId ?temp_ts }
}

SELECT ?temp ?tempType ?pointProp ?target WHERE {
  ?temp a brick:Zone_Air_Temperature_Sensor .
  ?temp rdfs:label ?l .
} LIMIT 5

SELECT ?zone ?zoneURI ?sp ?spURI ?ts ?tsURI ?spTS ?spTSURI
WHERE {
  ?sp brick:isPointOf ?zone .
  ?sp a brick:Zone_Air_Cooling_Temperature_Setpoint .
  ?ts brick:isPointOf ?zone .
  ?ts a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?sp ref:hasExternalReference ?spTSURI . ?spTSURI ref:hasTimeseriesId ?spTS }
  OPTIONAL { ?ts ref:hasExternalReference ?tsURI . ?tsURI ref:hasTimeseriesId ?ts }
}
LIMIT 40

SELECT ?zoneUri ?label WHERE {
  ?zoneUri a brick:HVAC_Zone .
  OPTIONAL { ?zoneUri rdfs:label ?label }
