import csv

TARGET_TS = "2018-07-02T17:00:00"

# zone name -> (spTS_ids list from CATALOG)
# The CATALOG links point_uri to timeseries_id directly
# So we read catalog to find which timeseries_id each point URI maps to

zones = {}
with open(CATALOG_CSV) as f:
    reader = csv.DictReader(f)
    for row in reader:
        point_uri = row["point_uri"]
        tsid = row["timeseries_id"]
        point_class = row["point_class"]

        # Extract zone name from point_uri: #Zone_F2_Z01.Zone_Air_Cooling_Temperature_Setpoint
        if ".Zone_Air_Cooling_Temperature_Setpoint" in point_uri:
            zone_key = point_uri.split("#")[-1].rsplit(".", 1)[0]  # Zone_F2_Z01
            if zone_key not in zones:
                zones[zone_key] = {}
            zones[zone_key]["spTsid"] = tsid
        elif ".Zone_Air_Temperature_Sensor" in point_uri:
            zone_key = point_uri.split("#")[-1].rsplit(".", 1)[0]
            if zone_key not in zones:
                zones[zone_key] = {}
            zones[zone_key]["tsTsid"] = tsid

print(f"Found {len(zones)} zones")

# Now read all values for target timestamp
values = {}
with open(VALUES_CSV) as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row["timestamp"] == TARGET_TS:
            values[row["timeseries_id"]] = float(row["value"])

print(f"Values at {TARGET_TS}: {len(values)} timeseries rows found")

results = {}
for zone_key, info in sorted(zones.items()):
    sp_tsid = info.get("spTsid")
    ts_tsid = info.get("tsTsid")
    sp_val = values.get(sp_tsid)
    temp_val = values.get(ts_tsid)
    if sp_val is not None and temp_val is not None:
        diff = temp_val - sp_val
        results[zone_key] = diff
        print(f"  {zone_key}: temp={temp_val}, setpoint={sp_val}, diff={diff:.2f}")
    else:
        print(f"  {zone_key}: MISSING spTsid={sp_tsid} tsTsid={ts_tsid} (sp_val={sp_val}, temp_val={temp_val})")

print()
best = max(results, key=results.get)
print(f"BEST zone: {best}  diff={results[best]:.2f}°C")

